sys_variable_value.value:
(function(inputs, outputs) {
    var outputs_obj = {
        status: 'success',
        error_message: ''
    };

    try {
        var helper = new x_1815796_itsmgr_0.AiBotHelper();
        
        // 1. Defensive Check: Ensure Chat ID exists
        var chat_id = (inputs.chat_id) ? inputs.chat_id.toString().trim() : "";

        if (!chat_id) {
            outputs_obj.status = 'error';
            outputs_obj.error_message = "Error: A Chat ID is required to delete a session.";
        } else {
            // 2. Call the Helper Function
            var result = helper.deleteChatSession(chat_id);

            // 3. Handle Result
            if (!result.success) {
                outputs_obj.status = 'error';
                outputs_obj.error_message = result.error_message;
            }
        }

    } catch (ex) {
        outputs_obj.status = 'error';
        outputs_obj.error_message = "Action Exception: " + ex.message;
    }

    // Final Mapping to Action Outputs
    outputs.status = outputs_obj.status;
    outputs.error_message = outputs_obj.error_message;

})(inputs, outputs);

